/* Fast dominant eigenpair for small real square matrices (n <= NMAX).
 *
 * Self-contained: balancing + Householder Hessenberg reduction + complex
 * shifted QR iteration for the eigenvalues, then inverse iteration for the
 * eigenvector of the dominant eigenvalue.  Returns Py_None when it cannot
 * handle the input (the Python caller then falls back to numpy.linalg.eig).
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <complex.h>
#include <math.h>
#include <string.h>

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>

#define NMAX 16
#define DEPS 2.220446049250313e-16

typedef double _Complex cplx;

/* --------------------------------------------------------------- */
/* balance a real matrix in place (EISPACK balanc, radix 2)          */
static void balance_mat(double *a, int n, double *scale)
{
    const double radix = 2.0, sqrdx = 4.0;
    int i, j, last = 0;
    for (i = 0; i < n; i++) scale[i] = 1.0;
    while (!last) {
        last = 1;
        for (i = 0; i < n; i++) {
            double c = 0.0, r = 0.0, g, f, s;
            for (j = 0; j < n; j++)
                if (j != i) { c += fabs(a[j * n + i]); r += fabs(a[i * n + j]); }
            if (c != 0.0 && r != 0.0) {
                g = r / radix; f = 1.0; s = c + r;
                while (c < g) { f *= radix; c *= sqrdx; }
                g = r * radix;
                while (c > g) { f /= radix; c /= sqrdx; }
                if ((c + r) / f < 0.95 * s) {
                    last = 0;
                    g = 1.0 / f;
                    for (j = 0; j < n; j++) a[i * n + j] *= g;
                    for (j = 0; j < n; j++) a[j * n + i] *= f;
                    scale[i] *= f;
                }
            }
        }
    }
}

/* --------------------------------------------------------------- */
/* Householder reduction to upper Hessenberg form, in place          */
static void hessenberg(double *a, int n)
{
    int k, i, j;
    double v[NMAX];
    for (k = 0; k + 2 < n; k++) {
        double nrm = 0.0, alpha, vn, beta;
        for (i = k + 1; i < n; i++) nrm += a[i * n + k] * a[i * n + k];
        if (nrm == 0.0) continue;
        nrm = sqrt(nrm);
        alpha = (a[(k + 1) * n + k] >= 0.0) ? -nrm : nrm;
        vn = 0.0;
        for (i = k + 1; i < n; i++) v[i] = a[i * n + k];
        v[k + 1] -= alpha;
        for (i = k + 1; i < n; i++) vn += v[i] * v[i];
        if (vn == 0.0) continue;
        beta = 2.0 / vn;
        /* A <- (I - beta v v^T) A   (rows k+1..n-1, cols k..n-1) */
        for (j = k; j < n; j++) {
            double s = 0.0;
            for (i = k + 1; i < n; i++) s += v[i] * a[i * n + j];
            s *= beta;
            for (i = k + 1; i < n; i++) a[i * n + j] -= s * v[i];
        }
        /* A <- A (I - beta v v^T)   (all rows, cols k+1..n-1) */
        for (i = 0; i < n; i++) {
            double s = 0.0;
            for (j = k + 1; j < n; j++) s += a[i * n + j] * v[j];
            s *= beta;
            for (j = k + 1; j < n; j++) a[i * n + j] -= s * v[j];
        }
        for (i = k + 2; i < n; i++) a[i * n + k] = 0.0;
    }
}

/* --------------------------------------------------------------- */
/* eigenvalues of a complex upper Hessenberg matrix (shifted QR)     */
static int qr_eigvals(cplx *H, int n, cplx *w)
{
    int i, j, k, hi = n - 1, guard = 0;
    double hnorm = 0.0;
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++) hnorm += cabs(H[i * n + j]);
    if (!(hnorm > 0.0)) hnorm = 1.0;

    while (hi >= 0) {
        int iter = 0;
        while (1) {
            int l;
            if (++guard > 200 + 60 * n) return -1;
            l = hi;
            while (l > 0) {
                double s = cabs(H[(l - 1) * n + (l - 1)]) + cabs(H[l * n + l]);
                if (s == 0.0) s = hnorm;
                if (cabs(H[l * n + (l - 1)]) <= DEPS * s) { H[l * n + (l - 1)] = 0.0; break; }
                l--;
            }
            if (l == hi) { w[hi] = H[hi * n + hi]; hi -= 1; break; }
            if (l == hi - 1) {
                cplx a = H[l * n + l], b = H[l * n + hi];
                cplx c = H[hi * n + l], d = H[hi * n + hi];
                cplx tr = a + d, det = a * d - b * c;
                cplx disc = csqrt(tr * tr - 4.0 * det);
                w[hi] = 0.5 * (tr + disc);
                w[hi - 1] = 0.5 * (tr - disc);
                hi -= 2; break;
            }
            {
                cplx sigma, cs[NMAX], sn[NMAX];
                iter++;
                if (iter % 11 == 0) {
                    sigma = H[hi * n + hi] + cabs(H[hi * n + (hi - 1)]);
                } else {
                    cplx a = H[(hi - 1) * n + (hi - 1)], b = H[(hi - 1) * n + hi];
                    cplx c = H[hi * n + (hi - 1)], d = H[hi * n + hi];
                    cplx tr = a + d, det = a * d - b * c;
                    cplx disc = csqrt(tr * tr - 4.0 * det);
                    cplx r1 = 0.5 * (tr + disc), r2 = 0.5 * (tr - disc);
                    sigma = (cabs(r1 - d) <= cabs(r2 - d)) ? r1 : r2;
                }
                for (i = l; i <= hi; i++) H[i * n + i] -= sigma;
                for (k = l; k < hi; k++) {
                    cplx f = H[k * n + k], g = H[(k + 1) * n + k], c, s;
                    double af = cabs(f), ag = cabs(g), r = hypot(af, ag);
                    if (r == 0.0) { c = 1.0; s = 0.0; }
                    else { c = conj(f) / r; s = conj(g) / r; }
                    cs[k] = c; sn[k] = s;
                    for (j = k; j <= hi; j++) {
                        cplx t1 = H[k * n + j], t2 = H[(k + 1) * n + j];
                        H[k * n + j] = c * t1 + s * t2;
                        H[(k + 1) * n + j] = -conj(s) * t1 + conj(c) * t2;
                    }
                }
                for (k = l; k < hi; k++) {
                    cplx c = cs[k], s = sn[k];
                    int imax = (k + 2 <= hi) ? k + 2 : hi;
                    for (i = l; i <= imax; i++) {
                        cplx t1 = H[i * n + k], t2 = H[i * n + (k + 1)];
                        H[i * n + k] = conj(c) * t1 + conj(s) * t2;
                        H[i * n + (k + 1)] = -s * t1 + c * t2;
                    }
                }
                for (i = l; i <= hi; i++) H[i * n + i] += sigma;
            }
        }
    }
    return 0;
}

/* --------------------------------------------------------------- */
/* complex inverse iteration:  x ~ null vector of (B - lam I)        */
static void inv_iter_c(const double *B, int n, cplx lam, double bnorm, cplx *x)
{
    cplx M[NMAX * NMAX], y[NMAX];
    int i, j, k, it;
    double tol = DEPS * (bnorm + cabs(lam));
    if (!(tol > 0.0)) tol = DEPS;

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            M[i * n + j] = (i == j) ? (B[i * n + j] - lam) : (cplx)B[i * n + j];

    /* LU with partial pivoting, tiny pivots perturbed */
    for (k = 0; k < n; k++) {
        int p = k; double best = cabs(M[k * n + k]);
        for (i = k + 1; i < n; i++) {
            double v = cabs(M[i * n + k]);
            if (v > best) { best = v; p = i; }
        }
        if (p != k)
            for (j = 0; j < n; j++) { cplx t = M[k * n + j]; M[k * n + j] = M[p * n + j]; M[p * n + j] = t; }
        if (cabs(M[k * n + k]) < tol) M[k * n + k] = tol;
        for (i = k + 1; i < n; i++) {
            cplx m = M[i * n + k] / M[k * n + k];
            M[i * n + k] = m;
            if (m != 0.0)
                for (j = k + 1; j < n; j++) M[i * n + j] -= m * M[k * n + j];
        }
    }

    for (i = 0; i < n; i++) y[i] = 1.0;
    for (it = 0; it < 2; it++) {
        double s;
        /* forward solve L z = P y  (pivoting already folded into L rows) */
        if (it > 0) {
            for (i = 0; i < n; i++)
                for (j = 0; j < i; j++) y[i] -= M[i * n + j] * y[j];
        }
        /* back solve U x = z */
        for (i = n - 1; i >= 0; i--) {
            cplx t = y[i];
            for (j = i + 1; j < n; j++) t -= M[i * n + j] * y[j];
            y[i] = t / M[i * n + i];
        }
        s = 0.0;
        for (i = 0; i < n; i++) s += creal(y[i]) * creal(y[i]) + cimag(y[i]) * cimag(y[i]);
        s = 1.0 / sqrt(s);
        for (i = 0; i < n; i++) y[i] *= s;
    }
    for (i = 0; i < n; i++) x[i] = y[i];
}

/* --------------------------------------------------------------- */
static PyObject *dominant(PyObject *self, PyObject *arg)
{
    Py_buffer view;
    double A0[NMAX * NMAX], B[NMAX * NMAX], Hr[NMAX * NMAX], scale[NMAX];
    cplx Hc[NMAX * NMAX], w[NMAX], x[NMAX];
    double anorm = 0.0, bnorm = 0.0, maxabs, maximag, s;
    cplx lam;
    int n, i, j, best, allreal;
    npy_intp dims[1];
    PyObject *arr = NULL, *val = NULL, *res = NULL;

    if (PyObject_GetBuffer(arg, &view, PyBUF_FORMAT | PyBUF_ND | PyBUF_C_CONTIGUOUS) != 0) {
        PyErr_Clear();
        Py_RETURN_NONE;
    }
    if (view.ndim != 2 || view.shape[0] != view.shape[1] || view.shape[0] < 1 ||
        view.shape[0] > NMAX || view.itemsize != 8 ||
        view.format == NULL || strcmp(view.format, "d") != 0) {
        PyBuffer_Release(&view);
        Py_RETURN_NONE;
    }
    n = (int)view.shape[0];
    memcpy(A0, view.buf, (size_t)n * (size_t)n * sizeof(double));
    PyBuffer_Release(&view);

    for (i = 0; i < n; i++) {
        double r = 0.0;
        for (j = 0; j < n; j++) {
            double v = A0[i * n + j];
            if (!isfinite(v)) Py_RETURN_NONE;
            r += fabs(v);
        }
        if (r > anorm) anorm = r;
    }

    memcpy(B, A0, (size_t)n * (size_t)n * sizeof(double));
    balance_mat(B, n, scale);
    for (i = 0; i < n; i++) {
        double r = 0.0;
        for (j = 0; j < n; j++) r += fabs(B[i * n + j]);
        if (r > bnorm) bnorm = r;
    }

    memcpy(Hr, B, (size_t)n * (size_t)n * sizeof(double));
    hessenberg(Hr, n);
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++) Hc[i * n + j] = (cplx)Hr[i * n + j];
    if (qr_eigvals(Hc, n, w) != 0) Py_RETURN_NONE;

    best = 0; maxabs = -1.0; maximag = 0.0;
    for (i = 0; i < n; i++) {
        double m = cabs(w[i]);
        double im = fabs(cimag(w[i]));
        if (!isfinite(m)) Py_RETURN_NONE;
        if (m > maxabs) { maxabs = m; best = i; }
        if (im > maximag * 1.0) { if (im > maximag) maximag = im; }
    }
    lam = w[best];
    allreal = (maximag <= 1e-13 * (maxabs > 0.0 ? maxabs : 1.0));
    if (allreal) lam = creal(lam);

    inv_iter_c(B, n, lam, bnorm, x);

    /* undo balancing and normalise */
    s = 0.0;
    for (i = 0; i < n; i++) {
        x[i] *= scale[i];
        s += creal(x[i]) * creal(x[i]) + cimag(x[i]) * cimag(x[i]);
    }
    if (!(s > 0.0) || !isfinite(s)) Py_RETURN_NONE;
    s = 1.0 / sqrt(s);
    for (i = 0; i < n; i++) x[i] *= s;

    /* residual check against the original matrix */
    {
        double resid = 0.0;
        for (i = 0; i < n; i++) {
            cplx t = -lam * x[i];
            for (j = 0; j < n; j++) t += A0[i * n + j] * x[j];
            resid += cabs(t);
        }
        if (!(resid <= 1e-10 * (anorm + cabs(lam)) + 1e-300)) Py_RETURN_NONE;
    }

    if (allreal) {
        double xr[NMAX], mx = 0.0, ph_r = 1.0, ph_i = 0.0, nn = 0.0;
        int kbig = 0;
        for (i = 0; i < n; i++) {
            double m = cabs(x[i]);
            if (m > mx) { mx = m; kbig = i; }
        }
        if (mx > 0.0) { ph_r = creal(x[kbig]) / mx; ph_i = -cimag(x[kbig]) / mx; }
        for (i = 0; i < n; i++) {
            xr[i] = ph_r * creal(x[i]) - ph_i * cimag(x[i]);
            nn += xr[i] * xr[i];
        }
        nn = (nn > 0.0) ? 1.0 / sqrt(nn) : 1.0;
        for (i = 0; i < n; i++) xr[i] *= nn;
        /* verify the real vector still satisfies the equation */
        {
            double resid = 0.0, lr = creal(lam);
            for (i = 0; i < n; i++) {
                double t = -lr * xr[i];
                for (j = 0; j < n; j++) t += A0[i * n + j] * xr[j];
                resid += fabs(t);
            }
            if (!(resid <= 1e-10 * (anorm + fabs(lr)) + 1e-300)) Py_RETURN_NONE;
        }
        dims[0] = n;
        arr = PyArray_SimpleNew(1, dims, NPY_FLOAT64);
        if (arr == NULL) return NULL;
        memcpy(PyArray_DATA((PyArrayObject *)arr), xr, (size_t)n * sizeof(double));
        {
            double lr = creal(lam);
            PyArray_Descr *d = PyArray_DescrFromType(NPY_FLOAT64);
            val = PyArray_Scalar(&lr, d, NULL);
            Py_DECREF(d);
        }
    } else {
        dims[0] = n;
        arr = PyArray_SimpleNew(1, dims, NPY_COMPLEX128);
        if (arr == NULL) return NULL;
        {
            double *p = (double *)PyArray_DATA((PyArrayObject *)arr);
            for (i = 0; i < n; i++) { p[2 * i] = creal(x[i]); p[2 * i + 1] = cimag(x[i]); }
        }
        {
            double lc[2];
            PyArray_Descr *d = PyArray_DescrFromType(NPY_COMPLEX128);
            lc[0] = creal(lam); lc[1] = cimag(lam);
            val = PyArray_Scalar(lc, d, NULL);
            Py_DECREF(d);
        }
    }
    if (val == NULL) { Py_XDECREF(arr); return NULL; }
    res = PyTuple_New(2);
    if (res == NULL) { Py_DECREF(arr); Py_DECREF(val); return NULL; }
    PyTuple_SET_ITEM(res, 0, val);
    PyTuple_SET_ITEM(res, 1, arr);
    return res;
}

static PyMethodDef methods[] = {
    {"dominant", dominant, METH_O, "Dominant eigenvalue/eigenvector of a small real square matrix."},
